const hl=t=>t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/(\/\/.*)|("[^"]*")|(@\w+)|\b(public|class|extends|new|while|if|else|for|break|return|double|int|boolean|void|enum|switch|case|true|false|static)\b|\b(\d+\.?\d*)\b/g,(m,a,b,c,d)=>`<span class="${a?"cm":b?"st":c?"an":d?"kw":"nm"}">${m}</span>`);
const U=[{t:"Fundamentos do FTC",d:"Programe seu robô em Java",l:[
{n:"OpModes",d:"O programa do robô",s:[["O que é um OpMode","Um OpMode é o programa que roda no Control Hub. O TeleOp é dirigido pelos pilotos e o Autonomous roda sozinho. Sua classe estende LinearOpMode e o código fica dentro de runOpMode().","@TeleOp(name = \"Meu TeleOp\")\npublic class MeuTeleOp extends LinearOpMode {\n  @Override\n  public void runOpMode() {\n    waitForStart();\n    while (opModeIsActive()) {\n      // código do robô aqui\n    }\n  }\n}"],["Ciclo de vida","waitForStart() segura o programa até apertarem START. Depois, opModeIsActive() mantém o loop vivo até o STOP."]],q:[
["Qual anotação marca um OpMode controlado pelos pilotos?","@TeleOp","@Autonomous","@Disabled","@Override","@TeleOp é o período controlado; @Autonomous é o autônomo."],
["Qual método espera o botão START ser apertado?","waitForStart()","sleep()","init()","start()","waitForStart() pausa o código até o START."],
["Qual condição mantém o loop rodando enquanto o OpMode está ativo?","opModeIsActive()","isRunning()","true && stop()","opModeIsInit()","Use while (opModeIsActive()) no loop principal."]]},
{n:"Motores",d:"Girar rodas e mecanismos",s:[["Pegando o motor","O nome entre aspas precisa ser igual ao da configuração do robô no Driver Hub.","DcMotor esq = hardwareMap.get(DcMotor.class, \"esq\");\nesq.setDirection(DcMotor.Direction.REVERSE);\nesq.setPower(0.5);"],["Potência e sentido","setPower aceita de -1.0 a 1.0. Se um lado do robô anda para trás, inverta aquele motor com REVERSE."]],q:[
["Como pegar um motor configurado como “garra”?","hardwareMap.get(DcMotor.class, \"garra\")","new DcMotor(\"garra\")","gamepad1.get(\"garra\")","telemetry.get(\"garra\")","O hardwareMap devolve o hardware pelo nome da configuração."],
["Qual faixa de valores o setPower() aceita?","-1.0 a 1.0","0 a 255","0 a 100","-100 a 100","De -1.0 (ré total) a 1.0 (frente total)."],
["Um motor gira ao contrário. O que usar?","setDirection(DcMotor.Direction.REVERSE)","setPower(-2)","resetEncoder()","stop()","REVERSE inverte o sentido do motor."]]},
{n:"Gamepad",d:"Controle e telemetria",s:[["Lendo o controle","O joystick vai de -1 a 1. O eixo Y é invertido: empurrar para frente dá valor negativo, por isso usamos o sinal de menos.","double frente = -gamepad1.left_stick_y;\nmotor.setPower(frente);\ntelemetry.addData(\"Frente\", frente);\ntelemetry.update();"],["Telemetry","addData guarda uma linha e update() envia tudo ao Driver Hub. Use para conferir valores."]],q:[
["Qual o valor de left_stick_y com o joystick todo para frente?","-1.0","1.0","0","100","No FTC o eixo Y é invertido: para frente é negativo."],
["Qual comando envia o telemetry ao Driver Hub?","telemetry.update()","telemetry.send()","telemetry.flush()","print()","addData guarda; update() mostra na tela."],
["Qual expressão é true quando o botão A está apertado?","gamepad1.a","gamepad1.A()","gamepad.a1","gamepad1.press(a)","Os botões são campos booleanos, como gamepad1.a."]]}]},
{t:"Pedro Pathing",d:"Trajetórias precisas no autônomo",l:[
{n:"Poses",d:"Posição e direção",s:[["Posição e direção","Uma Pose tem x, y e heading. O heading é dado em radianos, então converta graus com Math.toRadians.","Pose inicio = new Pose(10, 60, Math.toRadians(0));\nfollower.setStartingPose(inicio);"],["Ponto de partida","Diga ao seguidor onde o robô começa com setStartingPose. Sem isso, as trajetórias saem deslocadas."]],q:[
["O que uma Pose guarda?","x, y e heading","só x e y","velocidade e aceleração","potência dos motores","Pose é a posição (x, y) mais a direção (heading)."],
["Em qual unidade é o heading no Pedro Pathing?","Radianos","Graus","Ticks","Polegadas","Use Math.toRadians() para converter."],
["Qual método define de onde o robô começa?","follower.setStartingPose(pose)","follower.begin(pose)","follower.reset()","pose.start()","setStartingPose informa a pose inicial."]]},
{n:"Paths",d:"Linhas e curvas",s:[["Linhas e curvas","BezierLine liga dois pontos em linha reta. BezierCurve usa pontos de controle para curvar. O pathBuilder monta tudo em um PathChain.","PathChain ir = follower.pathBuilder()\n  .addPath(new BezierLine(inicio, destino))\n  .setLinearHeadingInterpolation(\n    inicio.getHeading(), destino.getHeading())\n  .build();"],["Heading","setLinearHeadingInterpolation gira o robô aos poucos durante o caminho. Os nomes podem mudar entre versões da biblioteca."]],q:[
["Qual classe cria um caminho reto entre dois pontos?","BezierLine","BezierCurve","PathChain","Follower","BezierLine liga dois pontos em linha reta."],
["Qual classe é usada para fazer curvas?","BezierCurve","BezierLine","Pose","Constants","BezierCurve usa pontos de controle."],
["O que junta vários paths em sequência?","PathChain","PathList","PoseArray","Follower","PathChain encadeia paths em ordem."]]},
{n:"Follower",d:"Fazer o robô andar",s:[["Seguindo o caminho","followPath começa o movimento e isBusy() fica true até o robô chegar.","follower.followPath(ir);\nwhile (opModeIsActive()) {\n  follower.update();\n  if (!follower.isBusy()) break;\n}"],["Regra de ouro","Chame follower.update() em todo ciclo do loop. Sem isso o robô não se corrige e não anda."]],q:[
["Quando chamar follower.update()?","A cada ciclo do loop","Só uma vez no init","Só ao fim do autônomo","Nunca, é automático","update() atualiza posição e motores sempre."],
["Como mandar o robô seguir um PathChain?","follower.followPath(chain)","follower.go(chain)","chain.run()","follower.drive(chain)","followPath inicia o seguimento."],
["Qual método diz se ainda está seguindo um path?","follower.isBusy()","follower.isDone()","follower.status()","follower.running","isBusy() é true enquanto o robô está em movimento."]]}]}];
